using System.Text.Json.Nodes;
using SZA.AI.Proxy.Models;

namespace SZA.AI.Proxy.Services
{
    public interface IImage_Describer
    {
        // Replaces every image found in body["messages"] by a text description generated by the vision model.
        // The body is modified in place. Supports Ollama ("images") and OpenAI ("image_url" content parts).
        Task ReplaceImagesAsync(JsonNode body, ProviderConfig provider, ModelConfig visionModel, CancellationToken ct = default);
    }
}
